1	// Money is always signed integer minor units. Conversion must happen before calling.
2	export type Balance = { amountMinor: bigint | null; currencyCode: string };
3	
4	export function netWorth(balances: Balance[], currencyCode: string): bigint | null {
5	  if (balances.some(balance => balance.amountMinor === null || balance.currencyCode !== currencyCode)) return null;
6	  return balances.reduce((total, balance) => total + balance.amountMinor!, 0n);
7	}
8	
9	export type CashflowTransaction = {
10	  amountMinor: bigint;
11	  currencyCode: string;
12	  status: "posted" | "pending";
13	  kind: "ordinary" | "transfer" | "refund";
14	  reviewReasons?: string[];
15	};
16	
17	export function summarizeCashflow(transactions: CashflowTransaction[], currencyCode: string) {
18	  let incomeMinor = 0n;
19	  let spendingMinor = 0n;
20	  let excludedReviewRows = 0;
21	  for (const transaction of transactions) {
22	    if (transaction.status !== "posted") continue;
23	    if (transaction.reviewReasons?.length) { excludedReviewRows++; continue; }
24	    if (transaction.kind === "transfer") continue;
25	    if (transaction.currencyCode !== currencyCode) return null;
26	    if (transaction.kind === "refund") spendingMinor -= transaction.amountMinor;
27	    else if (transaction.amountMinor > 0n) incomeMinor += transaction.amountMinor;
28	    else spendingMinor -= transaction.amountMinor;
29	  }
30	  return { incomeMinor, spendingMinor, netMinor: incomeMinor - spendingMinor,
31	    ...(excludedReviewRows ? { excludedReviewRows, partial: true as const } : {}) };
32	}
33	
34	export type ForecastAccount = {
35	  id: string;
36	  currencyCode: string;
37	  balanceMinor: bigint | null;
38	  // A bank's available balance already includes pending holds. Use it instead of deducting holds again.
39	  availableMinor?: bigint | null;
40	  pendingHoldMinor?: bigint;
41	  reservedMinor?: bigint;
42	  safetyBufferMinor?: bigint;
43	  minimumMinor?: bigint;
44	};
45	
46	export type ForecastEvent = {
47	  date: string;
48	  accountId: string;
49	  expectedMinor: bigint;
50	  conservativeMinor?: bigint;
51	  optimisticMinor?: bigint;
52	  source?: "confirmed" | "estimated" | "debt" | "scenario";
53	  name?: string;
54	};
55	
56	export type ForecastInput = {
57	  workspaceBufferMinor?: bigint;
58	  startDate: string;
59	  horizonDays: number;
60	  currencyCode: string;
61	  accounts: ForecastAccount[];
62	  events: ForecastEvent[];
63	  scenarioEvents?: ForecastEvent[];
64	  missingInputs?: string[];
65	};
66	
67	type ForecastDay = {
68	  date: string;
69	  expectedMinor: bigint;
70	  conservativeMinor: bigint;
71	  optimisticMinor: bigint;
72	  conservativeByAccount: Record<string, bigint>;
73	};
74	
75	type ForecastResult =
76	  | { status: "unavailable"; missingInputs: string[] }
77	  | { status: "available"; days: ForecastDay[] };
78	
79	function parseDate(date: string): number {
80	  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) throw new Error(`Invalid date: ${date}`);
81	  const timestamp = Date.parse(`${date}T00:00:00Z`);
82	  if (!Number.isFinite(timestamp) || new Date(timestamp).toISOString().slice(0, 10) !== date) throw new Error(`Invalid date: ${date}`);
83	  return timestamp;
84	}
85	
86	export function forecastDaily(input: ForecastInput): ForecastResult {
87	  const start = parseDate(input.startDate);
88	  if (!Number.isSafeInteger(input.horizonDays) || input.horizonDays < 1 || input.horizonDays > 3660) throw new Error("Invalid forecast horizon");
89	  const ids = new Set(input.accounts.map(account => account.id));
90	  if (ids.size !== input.accounts.length) throw new Error("Duplicate account ID");
91	  const events = [...input.events, ...(input.scenarioEvents ?? [])];
92	  for (const event of events) {
93	    parseDate(event.date);
94	    if (!ids.has(event.accountId)) throw new Error(`Unknown account: ${event.accountId}`);
95	  }
96	  const missingInputs = [...(input.missingInputs ?? [])];
97	  if (!input.accounts.length) missingInputs.push("accounts");
98	  for (const account of input.accounts) {
99	    if (account.currencyCode !== input.currencyCode) missingInputs.push(`fx:${account.id}`);
100	    if (account.availableMinor == null && account.balanceMinor === null) missingInputs.push(`balance:${account.id}`);
101	    if (account.availableMinor === null) missingInputs.push(`available-balance:${account.id}`);
102	  }
103	  if (missingInputs.length) return { status: "unavailable", missingInputs };
104	
105	  const balances = new Map<string, { expected: bigint; conservative: bigint; optimistic: bigint }>(input.accounts.map(account => {
106	    const initial = account.availableMinor ?? account.balanceMinor! - (account.pendingHoldMinor ?? 0n);
107	    return [account.id, { expected: initial, conservative: initial, optimistic: initial }];
108	  }));
109	  const days: ForecastDay[] = [];
110	  for (let offset = 0; offset < input.horizonDays; offset++) {
111	    const date = new Date(start + offset * 86400000).toISOString().slice(0, 10);
112	    for (const event of events) {
