1	import { netWorth, summarizeCashflow, type CashflowTransaction } from "./calculations";
2	import { resolveBalances, type BalanceTransaction, type BalanceSnapshot } from "./balances";
3	import { goalContributionProjection } from "./goals";
4	import { budgetProgress, type MonthlyLimit } from "./spending-plans";
5	import { wealthEvidence, type WealthValue } from "./wealth";
6	import { buildSourceCoverage, type SourceCoverage, type loadSourceCoverageMetadata } from "./source-coverage";
7	
8	type Account = { id: string; name: string; currency_code: string };
9	type Transaction = { amount_minor: string; currency_code: string; status: string; kind: string; review_reasons?: string[] };
10	export type ReviewTransaction = Transaction & { id: string; account_id?: string; parent_transaction_id?: string; posted_on: string; category_id: string | null; merchant_id: string | null; refund_of_id?: string | null; refund_category_id?: string | null };
11	
12	export function reviewNetWorth(accountTotals: Record<string, string | null>, wealth: WealthValue[], today: string) {
13	  const dated = wealthEvidence(wealth, today);
14	  const currencies = [...new Set([...Object.keys(accountTotals), ...wealth.filter(row => !row.linked_account_id).map(row => row.currency_code)])];
15	  return Object.fromEntries(currencies.map(currency => {
16	    if (accountTotals[currency] === null || wealth.some(row => !row.linked_account_id && row.currency_code === currency && row.as_of > today)) return [currency, null];
17	    const total = BigInt(accountTotals[currency] ?? "0") + dated.included.filter(row => row.currencyCode === currency).reduce((sum, row) => sum + row.amountMinor, 0n);
18	    return [currency, total.toString()];
19	  }));
20	}
21	
22	export function buildPlanningReview(input: {
23	  today: string;
24	  goals: { id: string; name: string; currency_code: string; target_minor: string; recorded_saved_minor: string | null; saved_as_of: string | null; planned_monthly_minor: string; contribution_starts_on: string | null; target_date: string | null; status: string }[];
25	  allocations: { goal_id: string; amount_minor: string }[];
26	  budgets: { id: string; category_id: string; currency_code: string; limit_minor: string; enabled: boolean; rollover?: boolean; rollover_from?: string }[];
27	  budgetHistory?: (MonthlyLimit & { plan_id: string })[];
28	  budgetCoverage?: Record<string, SourceCoverage>;
29	  transactions: ReviewTransaction[];
30	  categories: { id: string; name: string }[];
31	}) {
32	  return {
