134	/** Calculated Scalable values, oldest first, and the items that tell where they stop. Disconnected connections count: their synced values still do. */
135	export async function loadScalableHistory(db: SupabaseClient, workspaceId: string) {
136	  const rows: CalculatedValue[] = [];
137	  for (let offset = 0; ; offset += 1000) {
138	    const { data, error } = await db.from("scalable_value_history").select("on_date, currency_code, total_minor::text").eq("workspace_id", workspaceId).order("on_date").range(offset, offset + 999);
139	    if (error) throw error;
140	    rows.push(...(data ?? []) as unknown as CalculatedValue[]);
141	    if (!data || data.length < 1000) break;
142	  }
143	  const connections = await db.from("scalable_connections").select("portfolio").eq("workspace_id", workspaceId).not("portfolio", "is", null);
144	  if (connections.error) throw connections.error;
145	  return { rows, knownIds: scalableKnownIds((connections.data ?? []).map(row => row.portfolio)) };
146	}
