322	
323	const SCALABLE_EVERY_MS = 15 * 60_000, BANK_EVERY_MS = 60 * 60_000;
324	// Tries that have not stamped last_synced_at yet: other tabs, or a sync that failed.
325	const tried = new Map<string, number>();
326	function due(connection: { id: string; last_synced_at: string | null }, everyMs: number) {
327	  const now = Date.now();
328	  const last = Math.max(connection.last_synced_at ? Date.parse(connection.last_synced_at) : 0, tried.get(connection.id) ?? 0);
329	  if (now - last < everyMs) return false;
330	  tried.set(connection.id, now);
331	  return true;
332	}
333	
334	// Opening or returning to Moneo: the page already shows the last numbers, and this answers once fresher ones have landed.
335	// The owner is present, so bank fetches carry PSU headers and don't use the background allowance. Failures are kept on the connection.
336	export async function POST(request: Request) {
337	  let context: Awaited<ReturnType<typeof requireWorkspace>>;
338	  try { context = await requireWorkspace(); } catch { return NextResponse.json({ error: "Unauthorized" }, { status: 401 }); }
339	  const { supabase, workspace } = context;
340	  const [scalable, banks] = await Promise.all([
341	    supabase.from("scalable_connections").select("id, last_synced_at").eq("workspace_id", workspace.id).eq("status", "active"),
342	    supabase.from("bank_connections").select("id, last_synced_at, sync_started_at").eq("workspace_id", workspace.id).eq("status", "active"),
343	  ]);
344	  if (scalable.error || banks.error) return NextResponse.json({ error: "Connections are unavailable" }, { status: 503 });
345	  const syncs: Promise<unknown>[] = [];
346	  if (scalableConfigured()) for (const row of scalable.data ?? []) if (due(row, SCALABLE_EVERY_MS)) syncs.push(syncScalable(row.id, workspace.id));
347	  if ((banks.data ?? []).length && process.env.SUPABASE_SERVICE_ROLE_KEY && await enableBankingConfigured()) for (const row of banks.data ?? [])
348	    if (!syncRunning(row) && due(row, BANK_EVERY_MS)) syncs.push(start(syncBankConnection, [row.id, workspace.id, psuFrom(request)]).then(run => run.returnValue));
349	  await Promise.allSettled(syncs);
350	  return NextResponse.json({ refresh: syncs.length > 0 });
351	}
