407	          {change !== null && <span className={tone(change)}>{signed(change, show(change))} since then</span>}<span>Today</span></p>
408	        {calculatedBefore && <p className="mt-2 text-xs text-muted-foreground">Days before {date(calculatedBefore)} are calculated from your transactions and past prices. Prices further than a year back are monthly.</p>}
409	      </> : <p className="text-sm text-muted-foreground">The value chart fills in day by day as Moneo syncs Scalable.</p>}
410	      {historyFailed && <p className="mt-2 text-xs text-muted-foreground">Earlier days could not be worked out, so this chart starts at your first sync.</p>}
411	    </div>
412	
413	    {total > 0n && <div>
414	      <div className="flex h-3 w-full overflow-hidden rounded-full bg-muted" aria-hidden>
415	        {slices.map((slice, index) => <span key={slice.name} className={SHADES[index % SHADES.length]} style={{ width: `${Number(slice.minor * 10000n / total) / 100}%` }} />)}
416	        {cash > 0n && <span className="bg-muted-foreground/30" style={{ width: `${Number(cash * 10000n / total) / 100}%` }} />}
417	      </div>
418	      <ul aria-label="Where the money is" className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-xs text-muted-foreground">
419	        {slices.map((slice, index) => <li key={slice.name} className="flex items-center gap-1.5"><span className={`size-2 rounded-full ${SHADES[index % SHADES.length]}`} />{slice.name} {pct(slice.minor, total)?.toFixed(0)}%</li>)}
420	        {cash > 0n && <li className="flex items-center gap-1.5"><span className="size-2 rounded-full bg-muted-foreground/30" />Cash {pct(cash, total)?.toFixed(0)}%</li>}
421	      </ul>
422	    </div>}
423	
424	    <div className="divide-y divide-border rounded-lg border border-border">
425	      {positions.map(item => {
426	        const value = BigInt(item.amount_minor), gain = item.cost_basis_minor === null ? null : value - BigInt(item.cost_basis_minor);
427	        return <div key={item.id} className="flex items-start justify-between gap-3 px-4 py-3">
428	          <div className="min-w-0"><p className="truncate font-medium">{item.name}</p>
429	            <p className="text-xs text-muted-foreground">{item.quantity_text} × {item.unit_price_text ? money(toMinor(item.unit_price_text, item.currency_code), item.currency_code) : "—"}</p></div>
430	          <div className="shrink-0 text-right"><p className="font-mono tabular-nums">{money(value, item.currency_code)}</p>
431	            {gain !== null && <p className={`font-mono text-xs tabular-nums ${tone(gain)}`}>{signed(gain, money(gain, item.currency_code))} {pctText(pct(gain, BigInt(item.cost_basis_minor!)))}</p>}</div>
432	        </div>;
433	      })}
434	      {BigInt(portfolio.cryptoMinor) > 0n && <div className="flex justify-between gap-3 px-4 py-3"><p className="font-medium">Crypto</p><p className="font-mono tabular-nums">{show(portfolio.cryptoMinor)}</p></div>}
435	      <div className="flex justify-between gap-3 px-4 py-3"><div><p className="font-medium">Cash to invest</p></div><p className="font-mono tabular-nums">{show(cash)}</p></div>
436	    </div>
437	
438	    {(portfolio.activity?.length ?? 0) > 0 && <div>
439	      <h3 className="text-xs font-medium text-muted-foreground">Recent activity</h3>
440	      <ul className="mt-2 space-y-1.5 text-sm">{portfolio.activity!.slice(0, 5).map(row => {
441	        const amount = row.amountMinor === null ? null : BigInt(row.amountMinor);
442	        return <li key={row.id} className="flex items-baseline justify-between gap-3">
443	          <span className="min-w-0 truncate"><span className="font-mono text-xs text-muted-foreground">{date(row.date)}</span> <span className="capitalize">{row.type}</span>{row.shares ? ` ${row.shares} ×` : ""} <span className="text-muted-foreground">{row.description}</span>{row.status !== "SETTLED" ? <span className="text-xs text-warning"> · {row.status.toLowerCase()}</span> : null}</span>
444	          {amount !== null && <span className={`shrink-0 font-mono tabular-nums ${amount > 0n ? "text-success" : ""}`}>{signed(amount, money(amount, row.currencyCode))}</span>}</li>;
445	      })}</ul>
446	    </div>}
447	
448	    {(portfolio.watchlist?.length ?? 0) > 0 && <div>
449	      <h3 className="text-xs font-medium text-muted-foreground">Watchlist</h3>
450	      <ul className="mt-2 flex flex-wrap gap-2 text-sm">{portfolio.watchlist!.map(item => <li key={item.isin} className="rounded-lg border border-border px-3 py-1.5">
451	        <span className="block max-w-56 truncate text-xs">{item.name}</span>
452	        <span className="font-mono tabular-nums">{item.priceMinor ? money(item.priceMinor, item.currencyCode) : "—"}</span>
453	        {item.dayPercent !== null && <span className={`ml-1.5 font-mono text-xs ${item.dayPercent > 0 ? "text-success" : item.dayPercent < 0 ? "text-danger" : "text-muted-foreground"}`}>{pctText(item.dayPercent)}</span>}</li>)}</ul>
454	    </div>}
455	  </section>;
456	}
