// Read-only: dumps Scalable transactions, cash breakdown, overview, holdings to scratchpad JSON. Only ALLOWED tools.
import { writeFileSync } from "node:fs";
import { serviceDb } from "@/lib/bank/server";
import { withScalable } from "@/lib/scalable/server";
const OUT = "C:/Users/mgsuk/AppData/Local/Temp/claude/3de23844519d7b87/02552df1-ba55-493f-b027-0eb78f9afe1e/scratchpad/";
const ALLOWED = new Set(["list_portfolio_transactions", "get_portfolio_holdings", "get_portfolio_overview", "get_portfolio_cash_breakdown"]);
type Row = Record<string, any>;
async function main() {
  const { data } = await serviceDb().from("scalable_connections").select("id, workspace_id").eq("status", "active").single();
  await withScalable(data!.id, data!.workspace_id, async mcp => {
    const call = (n: string, a: Row = {}) => { if (!ALLOWED.has(n)) throw new Error("blocked " + n); return mcp.callTool(n, a) as Promise<Row>; };
    const rows: Row[] = [], crypto: Row[] = []; let c: string | undefined, cc: string | undefined, sd = false, cd = false, pages = 0;
    while ((!sd || !cd) && pages++ < 200) {
      const p = await call("list_portfolio_transactions", { pageSize: 100, ...(c ? { cursor: c } : {}), ...(cc ? { cryptoCursor: cc } : {}) });
      if (!sd) rows.push(...(p.transactions ?? [])); if (!cd) crypto.push(...(p.crypto?.transactions ?? []));
      c = sd ? undefined : p.page?.nextCursor || undefined; cc = cd ? undefined : p.crypto?.page?.nextCursor || undefined; sd = !c; cd = !cc;
    }
    writeFileSync(OUT + "scalable-tx.json", JSON.stringify({ rows, crypto }, null, 0));
    writeFileSync(OUT + "scalable-now.json", JSON.stringify({ cash: await call("get_portfolio_cash_breakdown"), overview: await call("get_portfolio_overview", { includeYearToDate: true }), holdings: await call("get_portfolio_holdings") }, null, 0));
    console.log("rows", rows.length, "crypto", crypto.length, "pages", pages);
  });
}
main().catch(e => { console.error(String(e)); process.exit(1); });
// Read-only. Rebuilds Home's series, compares readers of "balance", and simulates corrected transfer timing. Writes only scratchpad JSON. No external calls.
import { readFileSync, writeFileSync } from "node:fs";
import { serviceDb } from "@/lib/bank/server";
import { calendarDate } from "@/lib/finance/calendar";
import { loadWealthItems, wealthEvidence } from "@/lib/finance/wealth";
import { loadBalanceEvidence, resolveBalances } from "@/lib/finance/balances";
import { buildReviewEvidence, reviewNetWorth } from "@/lib/finance/review";
import { currentNetWorth, dayRange, firstSyncedOn, loadScalableHistory, loadWealthEvents, monthEnds, netWorth, netWorthSeries, removedOn, valuationHistory } from "@/app/money/wealth/net-worth";
const OUT = "C:/Users/mgsuk/AppData/Local/Temp/claude/3de23844519d7b87/02552df1-ba55-493f-b027-0eb78f9afe1e/scratchpad/";
const eur = (v: bigint | number | undefined) => v === undefined ? "-" : (Number(v) / 100).toFixed(2);
async function main() {
  const db = serviceDb();
  const { data: conn } = await db.from("scalable_connections").select("workspace_id").eq("status", "active").single();
  const ws = conn!.workspace_id, tz = "Europe/Berlin", today = calendarDate(new Date(), tz);
  const [ev, events, items, hist] = await Promise.all([loadBalanceEvidence(db as never, ws), loadWealthEvents(db as never, ws), loadWealthItems(db as never, ws, true), loadScalableHistory(db as never, ws)]);
  const accounts = (ev.accounts as any[]).filter(a => !a.archived_at);
  const vals = valuationHistory(events, items), before = firstSyncedOn(vals, hist.knownIds);
  console.log("today", today, "before", before, "knownIds", hist.knownIds.size);
  const dates = dayRange(monthEnds(today, 12)[0], today);
  const base = { dates, timeZone: tz, snapshots: ev.snapshots as any, ledger: ev.ledger as any, valuations: vals, removedOn: removedOn(items, tz), calculated: { rows: hist.rows, before }, accountIds: new Set(accounts.map(a => a.id)) };
  const series = netWorthSeries(base as any);
  const active = items.filter(i => !i.removed_at), kinds = new Map(items.map(i => [i.id, i.kind]));
  const pref = resolveBalances(accounts, ev.snapshots, ev.ledger, ev.asOf, tz, undefined, { preferLatestRecorded: true });
  const strict = resolveBalances(accounts, ev.snapshots, ev.ledger, ev.asOf, tz);
  for (const [n, r] of [["prefer", pref], ["strict", strict]] as const) for (const a of r) console.log(n, a.name, a.balance.status, a.balance.amount_minor, a.balance.warnings.join(";"));
  const dated = wealthEvidence(active, today);
  const headline = currentNetWorth(today, pref, dated.included.map(v => ({ ...v, debt: kinds.get(v.id) === "debt" })));
  console.log("headline", eur(netWorth(headline).get("EUR")), "series last (raw)", eur(netWorth(series.at(-1)!).get("EUR")), "accts", eur(headline.accounts.get("EUR")), "assets", eur(headline.assets.get("EUR")));
