  const tx = JSON.parse(readFileSync(OUT + "scalable-tx.json", "utf8")).rows as any[];
  const cashT = tx.filter(r => r.cash && /DEPOSIT|WITHDRAWAL/.test(r.cash.transactionType)).map(r => ({ id: r.id as string, day: calendarDate(r.lastEventAt, tz), a: Math.round(Number(r.cash.amount) * 100), type: r.cash.transactionType }));
