  const ws = conn!.workspace_id;
  const { data: workspace } = await db.from("workspaces").select("*").eq("id", ws).single();
  const { data: settings } = await db.from("workspace_settings").select("timezone, base_currency, locale").eq("workspace_id", ws).maybeSingle();
  console.log("settings", JSON.stringify(settings), "workspace keys", Object.keys(workspace ?? {}).join(","));
